# Check connectivity via 4s, 5s, 0s from original 4 positions
# A 0 becomes 4 if it can reach an original 4 via a path of adjacent (8-way) 4s, 5s, 0s

def can_reach_4s_pos(r, c):
    """Check if position (r,c) can reach any original 4 via 8-connpath of 4s,5s,0s"""
    visited = set()
    queue = deque([(r, c)])
    visited.add((r, c))

    while queue:
        cur_r, cur_c = queue.popleft()
        # Check neighbors
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = cur_r + dr, cur_c + dc
                if 0 <= nr < len(inp) and 0 <= nc < len(inp[0]):
                    if (nr, nc) not in visited and inp[nr][nc] in [0, 4, 5]:
                        if (nr, nc) in inp_4s:
                            return True
                        visited.add((nr, nc))
                        queue.append((nr, nc))
    return False

# Test
