# through 4s and 5s?
def in_same_component(pos, reach_set):
    """Check if pos can reach the reached set through 4s, 5s, 0s"""
    visited = set()
    queue = deque([pos])
    visited.add(pos)
    while queue:
        pr, pc = queue.popleft()
        if (pr, pc) in reach_set:
            return True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = pr + dr, pc + dc
                if 0 <= nr < len(inp) and 0 <= nc < len(inp[0]):
                    if (nr, nc) not in visited and inp[nr][nc] in [0, 4, 5]:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
    return False

